60	// shouldStripExif checks if the MIME type is an image format that may contain EXIF metadata.
61	// Returns true for formats like JPEG, TIFF, WebP, HEIC, and HEIF which commonly contain
62	// privacy-sensitive metadata such as GPS coordinates, camera settings, and device information.
63	func shouldStripExif(mimeType string) bool {
64		return exifCapableImageTypes[mimeType]
65	}
